div.script:
tailwind.config = {
    darkMode: 'class',
    theme: {
        extend: {
            colors: {
                brand: {
                    50: '#f0f3ff',
                    500: '#6366f1',
                    600: '#4f46e5',
                    700: '#4338ca',
                    accent: '#a855f7',
                    cyan: '#06b6d4',
                    emerald: '#10b981'
                },
                dark: {
                    bg: '#0a0d14',
                    card: '#121824',
                    border: 'rgba(255, 255, 255, 0.08)'
                }
            },
            fontFamily: {
                sans: ['Plus Jakarta Sans', 'sans-serif'],
                mono: ['Fira Code', 'monospace']
            },
            animation: {
                'pulse-slow': 'pulse 4s cubic-bezier(0.4, 0, 0.6, 1) infinite',
                'glow': 'glow 3s ease-in-out infinite alternate',
            },
            keyframes: {
                glow: {
                    '0%': { 'box-shadow': '0 0 15px rgba(99, 102, 241, 0.3)' },
                    '100%': { 'box-shadow': '0 0 35px rgba(168, 85, 247, 0.6)' }
                }
            }
        }
    }
}

        const canvas = document.getElementById('bgCanvas');
        const ctx = canvas.getContext('2d');

        let width, height;
        let particles = [];

        function resizeCanvas() {
            width = canvas.width = window.innerWidth;
            height = canvas.height = window.innerHeight;
        }

        class Particle {
            constructor() {
                this.reset();
            }

            reset() {
                this.x = Math.random() * width;
                this.y = Math.random() * height;
                this.vx = (Math.random() - 0.5) * 0.4;
                this.vy = (Math.random() - 0.5) * 0.4;
                this.radius = Math.random() * 1.5 + 0.5;
                this.alpha = Math.random() * 0.5 + 0.2;
            }

            update() {
                this.x += this.vx;
                this.y += this.vy;

                if (this.x < 0 || this.x > width) this.vx *= -1;
                if (this.y < 0 || this.y > height) this.vy *= -1;
            }

            draw() {
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
                ctx.fillStyle = `rgba(168, 85, 247, ${this.alpha})`;
                ctx.fill();
            }
        }

        function initParticles() {
            particles = [];
            const count = Math.floor((width * height) / 18000);
            for (let i = 0; i < count; i++) {
                particles.push(new Particle());
            }
        }

        function animateParticles() {
            ctx.clearRect(0, 0, width, height);

            for (let i = 0; i < particles.length; i++) {
                particles[i].update();
                particles[i].draw();

                for (let j = i + 1; j < particles.length; j++) {
                    const dx = particles[i].x - particles[j].x;
                    const dy = particles[i].y - particles[j].y;
                    const dist = Math.sqrt(dx * dx + dy * dy);

                    if (dist < 110) {
                        ctx.beginPath();
                        ctx.moveTo(particles[i].x, particles[i].y);
                        ctx.lineTo(particles[j].x, particles[j].y);
                        ctx.strokeStyle = `rgba(99, 102, 241, ${0.12 * (1 - dist / 110)})`;
                        ctx.lineWidth = 0.6;
                        ctx.stroke();
                    }
                }
            }

            requestAnimationFrame(animateParticles);
        }

        window.addEventListener('resize', () => {
            resizeCanvas();
            initParticles();
        });

        resizeCanvas();
        initParticles();
        animateParticles();

        const openBtn = document.getElementById("openButton");
        const statusEl = document.getElementById("status");
        const toggleSourceBtn = document.getElementById("toggleSourceBtn");
        const sourceViewerPanel = document.getElementById("sourceViewerPanel");
        const sourceBtnText = document.getElementById("sourceBtnText");
        const copySourceBtn = document.getElementById("copySourceBtn");
        const sourceTextArea = document.getElementById("sourcePage");

        toggleSourceBtn.addEventListener("click", () => {
            const isHidden = sourceViewerPanel.classList.contains("hidden");
            if (isHidden) {
                sourceViewerPanel.classList.remove("hidden");
                sourceBtnText.textContent = "Hide Payload";
            } else {
                sourceViewerPanel.classList.add("hidden");
                sourceBtnText.textContent = "View Payload";
            }
        });

        copySourceBtn.addEventListener("click", () => {
            sourceTextArea.select();
            document.execCommand('copy');
            copySourceBtn.innerHTML = `<i class="fa-solid fa-check text-emerald-400"></i><span>Copied!</span>`;
            setTimeout(() => {
                copySourceBtn.innerHTML = `<i class="fa-regular fa-copy"></i><span>Copy Raw</span>`;
            }, 2000);
        });

        openBtn.addEventListener("click", function () {
            statusEl.innerHTML = `<i class="fa-solid fa-spinner animate-spin text-brand-cyan"></i><span class="text-brand-cyan">Launching stealth tab...</span>`;

            const newTab = window.open("about:blank", "_blank");

            if (!newTab) {
                statusEl.innerHTML = `<i class="fa-solid fa-triangle-exclamation text-amber-400"></i><span class="text-amber-400">Pop-up blocked! Allow pop-ups for this domain in Chrome settings.</span>`;
                return;
            }

            let suppliedHtml = sourceTextArea.value;

            // Inject History API override alongside base tag to prevent URL parameters
            const injection = `<head>
<script>
    history.pushState = function() {};
    history.replaceState = function() {};
<\/script>
<base href="https://daknux.github.io/">`;

            suppliedHtml = suppliedHtml.replace("<head>", injection);

            try {
                newTab.document.open();
                newTab.document.write(suppliedHtml);
                newTab.document.close();
                newTab.focus();

                statusEl.innerHTML = `<i class="fa-solid fa-circle-check text-emerald-400"></i><span class="text-emerald-400">Stealth portal deployed successfully!</span>`;
            } catch (error) {
                newTab.close();
                statusEl.innerHTML = `<i class="fa-solid fa-circle-xmark text-red-400"></i><span class="text-red-400">Execution failed: ${error.message}</span>`;
            }
        });
